import sys

def lcs_length(a: str, b: str) -> int:
    if not a or not b:
        return 0
    if len(a) < len(b):
        a, b = b, a
    # Hunt-Szymanski / bit-parallel Myers / Allison-Dix bitstring LCS
    # In Python, arbitrary precision ints make bit-parallel LCS O(N * M / word_size) extremely fast!
    pos = {}
    for i, ch in enumerate(b):
        pos.setdefault(ch, 0)
        pos[ch] |= 1 << i

    M = (1 << len(b)) - 1
    S = M
    for ch in a:
        P = pos.get(ch, 0)
        u = S & P
        S = (S + u) | (S - u)
    return len(b) - (S & M).bit_count()

def main():
    lines = sys.stdin.read().splitlines()
    if len(lines) < 2:
        a = lines[0] if lines else ""
        b = ""
    else:
        a, b = lines[0], lines[1]
    print(lcs_length(a, b))

if __name__ == "__main__":
    main()
